selectAiSetup.profileSql:
-- 1. CREATE_PROFILE은 DB 설정을 생성합니다. 이 앱에서 실행하지 마세요.
BEGIN DBMS_CLOUD_AI.CREATE_PROFILE(
  profile_name => '<PROFILE_NAME>',
  attributes => '{"provider":"oci","credential_name":"<CREDENTIAL_NAME>","model":"<MODEL>","object_list":[{"owner":"<SCHEMA>","name":"<TABLE>"}]}'); END;
/
-- 2. SET_PROFILE은 현재 stateful session에만 영향을 줍니다.
EXEC DBMS_CLOUD_AI.SET_PROFILE('<PROFILE_NAME>');
-- 3. SHOWSQL은 외부 AI 요청/비용이 발생할 수 있으며 SQL 정답을 보장하지 않습니다.
SELECT AI SHOWSQL '<QUESTION>';
-- Read-only catalog check:
SELECT attribute_name, attribute_value FROM user_cloud_ai_profile_attributes WHERE profile_name = '<PROFILE_NAME>' ORDER BY attribute_name;

-- 1. CREATE_PROFILE creates DB configuration. Do not run it from this app.
BEGIN DBMS_CLOUD_AI.CREATE_PROFILE(
  profile_name => '<PROFILE_NAME>',
  attributes => '{"provider":"oci","credential_name":"<CREDENTIAL_NAME>","model":"<MODEL>","object_list":[{"owner":"<SCHEMA>","name":"<TABLE>"}]}'); END;
/
-- 2. SET_PROFILE affects the current stateful session only.
EXEC DBMS_CLOUD_AI.SET_PROFILE('<PROFILE_NAME>');
-- 3. SHOWSQL can call external AI/incur cost and does not prove SQL correctness.
SELECT AI SHOWSQL '<QUESTION>';
-- Read-only catalog check:
SELECT attribute_name, attribute_value FROM user_cloud_ai_profile_attributes WHERE profile_name = '<PROFILE_NAME>' ORDER BY attribute_name;

-- 1. CREATE_PROFILE 会创建 DB 配置。请勿在本应用中执行。
BEGIN DBMS_CLOUD_AI.CREATE_PROFILE(
  profile_name => '<PROFILE_NAME>',
  attributes => '{"provider":"oci","credential_name":"<CREDENTIAL_NAME>","model":"<MODEL>","object_list":[{"owner":"<SCHEMA>","name":"<TABLE>"}]}'); END;
/
-- 2. SET_PROFILE 仅影响当前 stateful session。
EXEC DBMS_CLOUD_AI.SET_PROFILE('<PROFILE_NAME>');
-- 3. SHOWSQL 可能调用外部 AI/产生费用，且不证明 SQL 正确。
SELECT AI SHOWSQL '<QUESTION>';
-- Read-only catalog check:
SELECT attribute_name, attribute_value FROM user_cloud_ai_profile_attributes WHERE profile_name = '<PROFILE_NAME>' ORDER BY attribute_name;

-- 1. CREATE_PROFILE は DB 設定を作成します。このアプリでは実行しません。
BEGIN DBMS_CLOUD_AI.CREATE_PROFILE(
  profile_name => '<PROFILE_NAME>',
  attributes => '{"provider":"oci","credential_name":"<CREDENTIAL_NAME>","model":"<MODEL>","object_list":[{"owner":"<SCHEMA>","name":"<TABLE>"}]}'); END;
/
-- 2. SET_PROFILE は現在の stateful session のみに影響します。
EXEC DBMS_CLOUD_AI.SET_PROFILE('<PROFILE_NAME>');
-- 3. SHOWSQL は外部 AI 呼び出し/費用が発生する場合があり、SQL 正しさを保証しません。
SELECT AI SHOWSQL '<QUESTION>';
-- Read-only catalog check:
SELECT attribute_name, attribute_value FROM user_cloud_ai_profile_attributes WHERE profile_name = '<PROFILE_NAME>' ORDER BY attribute_name;
